<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;

/**
 * `myat_partner_files` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property int|null $cid
 * @property string|null $Attachment
 * @property string|null $Flnm
 * @property int|null $Type
 */
class MyatPartnerFile extends Model
{
    protected $table = 'myat_partner_files';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
            'cid' => 'integer',
            'Type' => 'integer',
        ];
    }

    /** The file itself is a blob in `Attachment`, as PHPRunner stores it. */
    protected $hidden = ['Attachment'];

    /** List columns without loading the blob, plus its size in bytes. */
    public function scopeWithoutBlob(Builder $query): Builder
    {
        return $query->select(['ID', 'cid', 'Flnm', 'Type'])
            ->selectRaw('OCTET_LENGTH(`Attachment`) as size_bytes');
    }
}
